public class InnerKnowledgeBaseManagedKnowledgeBaseConfigurationFactory(Action<Humidifier.Bedrock.KnowledgeBaseTypes.ManagedKnowledgeBaseConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.KnowledgeBaseTypes.ManagedKnowledgeBaseConfiguration>
{

    internal InnerKnowledgeBaseEmbeddingModelConfigurationFactory EmbeddingModelConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseSupplementalDataStorageConfigurationFactory SupplementalDataStorageConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseManagedKnowledgeBaseServerSideEncryptionConfigurationFactory ServerSideEncryptionConfigurationFactory { get; set; }

    protected override Humidifier.Bedrock.KnowledgeBaseTypes.ManagedKnowledgeBaseConfiguration Create()
    {
        var managedKnowledgeBaseConfigurationResult = CreateManagedKnowledgeBaseConfiguration();
        factoryAction?.Invoke(managedKnowledgeBaseConfigurationResult);

        return managedKnowledgeBaseConfigurationResult;
    }

    private Humidifier.Bedrock.KnowledgeBaseTypes.ManagedKnowledgeBaseConfiguration CreateManagedKnowledgeBaseConfiguration()
    {
        var managedKnowledgeBaseConfigurationResult = new Humidifier.Bedrock.KnowledgeBaseTypes.ManagedKnowledgeBaseConfiguration();

        return managedKnowledgeBaseConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.KnowledgeBaseTypes.ManagedKnowledgeBaseConfiguration result)
    {
        base.CreateChildren(result);

        result.EmbeddingModelConfiguration ??= EmbeddingModelConfigurationFactory?.Build();
        result.SupplementalDataStorageConfiguration ??= SupplementalDataStorageConfigurationFactory?.Build();
        result.ServerSideEncryptionConfiguration ??= ServerSideEncryptionConfigurationFactory?.Build();
    }

} // End Of Class

